//
// Committed data, like NazgHostLayoutTable.cpp, with no generator in the repo: QMK's names for
// each host layout's keys -- keymap_german.h's DE_SLSH -- from the extras files of a local QMK
// checkout (data/constants/keycodes/extras/keycodes_*_0.0.1.hjson). Each expression is resolved
// through the layout's own names, and QMK's US shifted names, to basic keycodes; S() is written
// LSFT(), ALGR() RALT(), A() LALT(). How to regenerate it: keycodes.md, "Regenerating the host
// layout names". 6582 names over 69 layouts.

