    std::span<const HostName> HostNamesOf(std::string_view layoutId) noexcept
    {
        const auto found = std::find_if(std::begin(c_Layouts), std::end(c_Layouts),
                                        [&](const LayoutNames& layout) { return layout.id == layoutId; });
        return found != std::end(c_Layouts) ? found->names : std::span<const HostName>{};
    }
